(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else{root.SlowMoSections=api;api.install();}})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
function parseTimestamp(value){const text=String(value).trim();if(!/^\d+(?::[0-5]?\d)?(?:\.\d{1,3})?$/.test(text))return NaN;const parts=text.split(':').map(Number);return parts.length===2?parts[0]*60+parts[1]:parts[0];}
function validSection(start,end,duration){return [start,end,duration].every(Number.isFinite)&&start>=0&&end-start>=.1&&end<=duration+.001;}
async function fingerprint(file,cryptoAPI=globalThis.crypto){
 // Bounded reads: matching survives filename/date changes without retaining a video.
 const length=65536,starts=[0,Math.max(0,Math.floor(file.size/2)-length/2),Math.max(0,file.size-length)];
 const samples=await Promise.all(starts.map(n=>file.slice(n,n+length).arrayBuffer()));
 const prefix=new TextEncoder().encode('SlowMo-sections-v1:'+file.size+':');const bytes=new Uint8Array(prefix.length+samples.reduce((n,b)=>n+b.byteLength,0));bytes.set(prefix);let cursor=prefix.length;for(const b of samples){bytes.set(new Uint8Array(b),cursor);cursor+=b.byteLength;}
 const hash=await cryptoAPI.subtle.digest('SHA-256',bytes);return 'v1-'+Array.from(new Uint8Array(hash),n=>n.toString(16).padStart(2,'0')).join('');
}
function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('slowmo-sections',1);let expired=false;const timer=setTimeout(()=>{expired=true;reject(new Error('Section storage is busy. Close other SlowMo windows and try again.'));},5000);r.onupgradeneeded=()=>r.result.createObjectStore('sections',{keyPath:'id'}).createIndex('videoKey','videoKey');r.onsuccess=()=>{clearTimeout(timer);if(expired)r.result.close();else resolve(r.result);};r.onerror=r.onblocked=()=>{expired=true;clearTimeout(timer);reject(new Error('Section storage is unavailable.'));};});}
async function request(mode,action){const connection=await db();return new Promise((resolve,reject)=>{let value;const tx=connection.transaction('sections',mode);try{const r=action(tx.objectStore('sections'));r.onsuccess=()=>value=r.result;}catch(e){connection.close();reject(e);return;}tx.oncomplete=()=>{connection.close();resolve(value);};tx.onabort=tx.onerror=()=>{connection.close();reject(tx.error||new Error('Section save failed.'));};});}
const storage={list:key=>request('readonly',s=>s.index('videoKey').getAll(key)),save:row=>request('readwrite',s=>s.put(row)),remove:id=>request('readwrite',s=>s.delete(id))};
function install(store=storage){
 let videoKey=null,rows=[],token=0,editing=null,ready=Promise.resolve(),mutating=false;
 const busy=value=>{mutating=value;for(const id of ['sectionName','sectionStart','sectionEnd','sectionRememberSpeed','deleteSection','saveSection','cancelSectionEdit'])$(id).disabled=value;$('sectionEditor').querySelector('[type="submit"]').disabled=value;};
 const say=text=>$('sectionsStatus').textContent=text;
 const change=dance.beforeReferenceChange.bind(dance);
 dance.beforeReferenceChange=selected=>{if(!change(selected))return false;const serial=++token;videoKey=null;rows=[];editing=null;$('sectionEditor').hidden=true;ready=fingerprint(selected).then(async key=>{if(serial!==token)return;const saved=await store.list(key);if(serial!==token)return;videoKey=key;rows=saved;render();}).catch(()=>{if(serial===token)say('Bookmarks are unavailable in this browser storage. Your video still plays normally.');});return true;};
 function render(){const list=$('sectionsList');list.replaceChildren();rows.sort((a,b)=>a.start-b.start||a.created-b.created);for(const row of rows){const container=document.createElement('div');container.className='section-row';const load=document.createElement('button');load.className='section-load';load.textContent=row.name;const note=document.createElement('small');note.textContent=precise(row.start)+'–'+precise(row.end)+(row.rate?' · '+row.rate.toFixed(2)+'×':'');load.append(note);load.onclick=()=>restore(row);const edit=document.createElement('button');edit.className='section-edit';edit.textContent='Edit';edit.setAttribute('aria-label','Edit '+row.name);edit.onclick=()=>editor(row);container.append(load,edit);list.append(container);}$('saveSection').disabled=mutating||!videoKey||!loopOn||!validSection(loopA,loopB,video.duration);}
 async function restore(row){if(!validSection(row.start,row.end,video.duration)){say('This section is outside this video. Edit its timestamps.');return;}const bounds=dance.comparisonBounds();if(bounds&&(row.start<bounds.start||row.end>bounds.end)){say('This section is outside the synchronized overlap. Realign the videos or open it in Watch.');return;}pausePlayback();if(row.rate)setSpeed(row.rate);loopA=row.start;loopB=row.end;loopOn=true;renderLoop();video.currentTime=row.start;time();$('sectionsDialog').close();await attemptPlay();}
 function editor(row=null){if(mutating)return;editing=row;$('sectionEditor').hidden=false;$('sectionEditorTitle').textContent=row?'Edit section':'Save section';$('sectionName').value=row?.name||'';$('sectionStart').value=(row?.start??loopA??0).toFixed(2);$('sectionEnd').value=(row?.end??loopB??0).toFixed(2);$('sectionRememberSpeed').checked=row?!!row.rate:true;$('deleteSection').hidden=!row;$('sectionName').focus({preventScroll:true});}
 const remove=document.createElement('button');remove.id='deleteSection';remove.type='button';remove.textContent='Delete section';remove.hidden=true;$('sectionEditor').append(remove);
 remove.onclick=async()=>{if(!editing||mutating)return;const row=editing,serial=token;busy(true);try{await store.remove(row.id);if(serial!==token)return;rows=rows.filter(r=>r.id!==row.id);$('sectionEditor').hidden=true;render();say('Section deleted.');}catch(e){if(serial===token)say(e.message);}finally{busy(false);render();}};
 $('openSections').onclick=async()=>{if(dance.locked)return;pausePlayback();openPlayerDialog('sectionsDialog');$('sectionEditor').hidden=true;say('Finding sections for this video…');const serial=token;await ready;if(serial!==token||!$('sectionsDialog').open)return;render();say(videoKey?'Tap a section to start its loop.':'Sections could not be matched for this video. Try selecting it again.');};
 document.querySelector('[data-close="sectionsDialog"]').onclick=()=>$('sectionsDialog').close();$('saveSection').onclick=()=>editor();$('cancelSectionEdit').onclick=()=>$('sectionEditor').hidden=true;
 $('sectionEditor').onsubmit=async e=>{e.preventDefault();if(!videoKey||mutating)return;const serial=token;const start=parseTimestamp($('sectionStart').value),end=parseTimestamp($('sectionEnd').value);if(!validSection(start,end,video.duration)){say('Use valid timestamps with B at least 0.1 seconds after A and within this video.');return;}const row={id:editing?.id||crypto.randomUUID(),videoKey,name:$('sectionName').value.trim()||'Section '+precise(start)+'–'+precise(end),start,end,rate:$('sectionRememberSpeed').checked?preferred:null,created:editing?.created||Date.now()};busy(true);try{await store.save(row);if(serial!==token)return;rows=rows.filter(r=>r.id!==row.id);rows.push(row);$('sectionEditor').hidden=true;render();say('Saved on this device.');}catch{if(serial===token)say('Could not save this section. Browser storage may be unavailable or full.');}finally{busy(false);render();}};
}
return {parseTimestamp,validSection,fingerprint,install};
});
